from math import gcd

# Test with different rules

def solve_line_between_6s():
    """Fill 3s on lines between all pairs of 6s."""
    output = [[4]*10 for _ in range(28)]
    positions = [(1,2), (3,3), (9,9), (10,4), (13,6), (18,2), (21,7), (22,2), (21,4)]

    for r, c in positions:
        output[r][c] = 7

    def points_on_segment(p1, p2):
        x1, y1 = p1
        x2, y2 = p2
        dx = x2 - x1
        dy = y2 - y1
        g = gcd(abs(dx), abs(dy))
        if g == 0:
            return []
        result = []
        for k in range(g + 1):
            px = x1 + k * (dx // g)
            py = y1 + k * (dy // g)
            result.append((px, py))
        return result

    for i in range(len(positions)):
        for j in range(i + 1, len(positions)):
            pts = points_on_segment(positions[i], positions[j])
            for pr, pc in pts:
                if 0 <= pr < 28 and 0 <= pc < 10:
                    output[pr][pc] = 3
    return output

